    private void comboBoxPersonasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_comboBoxPersonasActionPerformed
        Person person = (Person) ((JComboBox)evt.getSource()).getSelectedItem();
        
        txtFieldName.setText(person.getName());
        txtFieldLastName.setText(person.getLastName());
        txtFieldAge.setText(person.getAge() + "");
        
        colocarImagen(person);
    }//GEN-LAST:event_comboBoxPersonasActionPerformed

    private void tableMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tableMouseClicked
        // TODO add your handling code here:
        int row = table.getSelectedRow();
        String name = (String) ((DefaultTableModel) table.getModel()).getValueAt(row, 0);
        String lastName = (String) ((DefaultTableModel) table.getModel()).getValueAt(row, 1);
                
        Person person = modelo.searchPerson(modelo.getArrayPerson(), name, lastName);

        if (person != null) {
            txtFieldName.setText(person.getName());
            txtFieldLastName.setText(person.getLastName());
            txtFieldAge.setText(person.getAge() + "");
        }
              
        colocarImagen(person);
    }//GEN-LAST:event_tableMouseClicked

    private void btnInsertarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnInsertarActionPerformed
        modelo.registrarPersona();        
        
        Person person = modelo.getPersons().get(modelo.getPersons().size() - 1);
        
        comboBoxPersonas.addItem(person);
        
        String[] personData = {person.getName(), person.getLastName(), person.getAge() + ""};
        
        ((DefaultTableModel) table.getModel()).addRow(personData);        
    }//GEN-LAST:event_btnInsertarActionPerformed
       
    private void colocarImagen(Person person) {
        ImageIcon image = new ImageIcon("src\\gui\\images\\" + person.getName() + 
        person.getLastName() + ".png");        
        lblImage.setIcon(image);
        
        if (image != null)
            image.setImage(image.getImage().getScaledInstance(lblImage.getWidth(), 
            lblImage.getHeight(), 0));            
    }
    
